import bisect

class BTreeNode:
    def __init__(self, is_leaf=True):
        self.is_leaf = is_leaf
        self.keys = []
        self.children = []

class BTree:
    def __init__(self, order=3):
        if order < 3:
            raise ValueError("Order must be >= 3")
        self.order = order
        self.max_keys = order - 1
        self.root = BTreeNode(is_leaf=True)

    def insert(self, key: int) -> None:
        promoted, new_right = self._insert(self.root, key)
        if promoted is not None:
            new_root = BTreeNode(is_leaf=False)
            new_root.keys = [promoted]
            new_root.children = [self.root, new_right]
            self.root = new_root

    def _insert(self, node: BTreeNode, key: int):
        if key in node.keys:
            return None, None
        if node.is_leaf:
            bisect.insort(node.keys, key)
            if len(node.keys) > self.max_keys:
                return self._split(node)
            return None, None

        idx = bisect.bisect_right(node.keys, key)
        promoted, new_child = self._insert(node.children[idx], key)
        if promoted is not None:
            node.keys.insert(idx, promoted)
            node.children.insert(idx + 1, new_child)
            if len(node.keys) > self.max_keys:
                return self._split(node)
        return None, None

    def _split(self, node: BTreeNode):
        mid = len(node.keys) // 2
        promoted = node.keys[mid]
        right = BTreeNode(is_leaf=node.is_leaf)
        right.keys = node.keys[mid + 1:]
        node.keys = node.keys[:mid]
        if not node.is_leaf:
            right.children = node.children[mid + 1:]
            node.children = node.children[:mid + 1]
        return promoted, right

    def search(self, key: int) -> bool:
        curr = self.root
        while curr:
            idx = bisect.bisect_left(curr.keys, key)
            if idx < len(curr.keys) and curr.keys[idx] == key:
                return True
            if curr.is_leaf:
                return False
            curr = curr.children[idx]
        return False

    def inorder_keys(self) -> list[int]:
        def _traverse(node):
            if not node or not node.keys:
                return []
            res = []
            for i in range(len(node.keys)):
                if not node.is_leaf and i < len(node.children):
                    res.extend(_traverse(node.children[i]))
                res.append(node.keys[i])
            if not node.is_leaf and len(node.children) > len(node.keys):
                res.extend(_traverse(node.children[-1]))
            return res
        return _traverse(self.root)

    def height(self) -> int:
        if not self.root or not self.root.keys:
            return 0
        h = 0
        curr = self.root
        while curr:
            h += 1
            if curr.is_leaf or not curr.children:
                break
            curr = curr.children[0]
        return h
